import { collections } from "./collections";

/**
 * Product seed data — imported from the live Threaded Hope shop.
 * ── EDIT HERE ── to change the catalog. Each entry is a plain object; the
 * `slug` and placeholder `image` are derived automatically from the name +
 * collection, so you only need to fill in the fields below.
 *
 * Fields:
 *  - collection : slug from collections.ts
 *  - name       : display name
 *  - price      : US dollars (lowest variant price when sizes vary)
 *  - description: short blurb shown on cards & product page
 *  - variants   : optional selectable options (e.g. size / color)
 *  - inStock    : stock status (defaults to true)
 *  - featured   : show on the home page
 *  - createdAt  : ISO date, used for "newest" sorting
 *  - image      : real product photo (Threaded Hope Shopify CDN)
 */
export type Variant = {
  name: string; // e.g. "Size"
  options: string[]; // e.g. ["S", "M", "L"]
};

export type ProductSeed = {
  collection: string;
  name: string;
  price: number;
  description: string;
  variants?: Variant[];
  inStock?: boolean;
  featured?: boolean;
  createdAt?: string;
  image?: string;
};

export type Product = Required<
  Omit<ProductSeed, "variants" | "createdAt" | "image">
> & {
  slug: string;
  variants: Variant[];
  createdAt: string;
  collectionName: string;
  hue: number;
  /** Real product photo URL; falls back to a generated placeholder. */
  image?: string;
};

